        expose TraceRequirements::rightSpecification;
        expose TraceRequirements::unlinkedCapacity;
        expose TraceRequirements::excludedCapacity;
        expose TraceRequirements::leftSpecification::leftCapacity;
        expose TraceRequirements::rightSpecification::rightCapacity;
    }
    view overview : GeneralView {
        expose TraceRequirements;
        expose TraceSystem;
    }
}

package RoverBehavior {
    action def InspectRoute {
        doc /* Declared mission order; this diagram does not execute the rover. */
        first start;
        action checkBattery;
        action patrol;
        action detectObstacle;
        action captureInspection;
        action transmitReport;
        action returnToDock;
        action recharge;
        done;
        succession first start then checkBattery;
        succession first checkBattery then patrol;
        succession first patrol then detectObstacle;
        succession first detectObstacle then captureInspection;
        succession first captureInspection then transmitReport;
        succession first transmitReport then returnToDock;
        succession first returnToDock then recharge;
        succession first recharge then done;
        allocation perceptionResponsibility allocate detectObstacle to RoverSystem::rover.autonomy.controller;
        allocation imagingResponsibility allocate captureInspection to RoverSystem::rover.inspection.camera;
        allocation reportingResponsibility allocate transmitReport to RoverSystem::rover.inspection.radio;
        allocation tractionResponsibility allocate patrol to RoverSystem::rover.mobility.leftDrive;
    }
    state def OperatingMode {
        entry; then docked;
        state docked;
        state patrolling;
        state inspecting;
        state returning;
        state charging;
        state safeStop;
        transition dispatch first docked then patrolling;
        transition targetFound first patrolling then inspecting;
        transition inspectionComplete first inspecting then patrolling;
        transition lowReserve first patrolling then returning;
        transition dockReached first returning then charging;
        transition chargeComplete first charging then docked;
        transition obstacleDetected first patrolling then safeStop;
        transition pathClear first safeStop then patrolling;
    }
}

package RoverComponents {
    private import ScalarValues::*;
    private import RoverTypes::*;
    part def Battery {
        doc /* Rechargeable battery. Capacity and reserve are design targets. */
        attribute capacityWh : Real default = 480.0;
        attribute reservePercent : Real default = 20.0;
        out port supply : PowerPort;
    }
    part def Distribution {
        in port input : PowerPort;
        out port drive : PowerPort;
        out port compute : PowerPort;
        out port payload : PowerPort;
    }
    part def Actuator;
    part def Sensor;
    part def Drive :> Actuator {
        attribute maximumSpeedMps : Real default = 1.5;
        in port power : PowerPort;
        in port command : CommandPort;
    }
    part def Controller {
        attribute obstacleStopDistanceM : Real default = 0.8;
        in port power : PowerPort;
        in port perception : SensorPort;
        in port images : ImagePort;
        out port drive : CommandPort;
        out port status : TelemetryPort;
    }
    part def Lidar :> Sensor {
        attribute rangeM : Real default = 12.0;
        out port scan : SensorPort;
    }
    part def Camera :> Sensor {
        attribute resolutionMP : Real default = 12.0;
        in port power : PowerPort;
        out port image : ImagePort;
    }
    part def Radio {
        attribute rangeM : Real default = 300.0;
        in port telemetry : TelemetryPort;
    }
}

package RoverRequirements {
    private import ScalarValues::*;
    private import RoverComponents::*;
    requirement def <'RVR-001'> EnergyReserve {
        doc /* Keep at least 20 percent battery reserve for the return journey. */
        subject battery : Battery;
        require constraint { battery.reservePercent >= 20.0 }
    }
    requirement def <'RVR-002'> SafeSpeed {
        doc /* Each drive shall limit nominal indoor speed to 1.5 m/s. */
        subject drive : Drive;
        require constraint { drive.maximumSpeedMps <= 1.5 }
    }
    requirement def <'RVR-003'> ObstacleClearance {
        doc /* Stop at least 0.8 m before a detected obstacle. */
        subject controller : Controller;
        require constraint { controller.obstacleStopDistanceM >= 0.8 }
    }
    requirement def <'RVR-004'> InspectionQuality {
        doc /* Capture inspection images at a resolution of at least 12 MP. */
        subject camera : Camera;
        require constraint { camera.resolutionMP >= 12.0 }
    }
    requirement <'RVR-RESERVE'> reserve : EnergyReserve {
        doc /* Keep at least 20 percent battery reserve for the return journey. */
        subject battery = RoverSystem::rover.energy.battery;
    }
    requirement <'RVR-SPEED'> speed : SafeSpeed {
        doc /* Limit the left drive nominal indoor speed to 1.5 m/s. */
        subject drive = RoverSystem::rover.mobility.leftDrive;
    }
    requirement <'RVR-CLEAR'> clearance : ObstacleClearance {
        doc /* Stop at least 0.8 m before a detected obstacle. */
        subject controller = RoverSystem::rover.autonomy.controller;
    }
    requirement <'RVR-IMAGE'> imaging : InspectionQuality {
        doc /* Capture inspection images at a resolution of at least 12 MP. */
        subject camera = RoverSystem::rover.inspection.camera;
    }
    assert satisfy reserve by RoverSystem::rover.energy.battery;
    assert satisfy speed by RoverSystem::rover.mobility.leftDrive;
    assert satisfy clearance by RoverSystem::rover.autonomy.controller;
    assert satisfy imaging by RoverSystem::rover.inspection.camera;
}

package RoverSystem {
    private import RoverComponents::*;
    part def InspectionRover {
        doc /* A slow indoor inspection rover. Explore architecture, mission,
               operating states and declared requirement traceability. */
        part energy {
            part battery : Battery;
            part distribution : Distribution;
            connection batterySupply connect battery.supply to distribution.input;
        }
        part mobility {
            part leftDrive : Drive;
            part rightDrive : Drive;
        }
        part autonomy {
            part controller : Controller;
            part lidar : Lidar;
            connection obstacleScan connect lidar.scan to controller.perception;
        }
        part inspection {
            part camera : Camera;
            part radio : Radio;
        }
        connection leftPower connect energy.distribution.drive to mobility.leftDrive.power;
        connection rightPower connect energy.distribution.drive to mobility.rightDrive.power;
        connection computePower connect energy.distribution.compute to autonomy.controller.power;
        connection cameraPower connect energy.distribution.payload to inspection.camera.power;
        connection leftCommand connect autonomy.controller.drive to mobility.leftDrive.command;
        connection rightCommand connect autonomy.controller.drive to mobility.rightDrive.command;
        connection inspectionImages connect inspection.camera.image to autonomy.controller.images;
        connection missionTelemetry connect autonomy.controller.status to inspection.radio.telemetry;
    }
    part rover : InspectionRover;
}

