package CompressorBehavior {
    private import CompressorTypes::*;
    private import CompressorComponents::*;
    action def SensePressure { out item reading : PressureReading; }
    action def SenseTemperature { out item reading : TemperatureReading; }
    action def ControlMotor {
        in item reading : PressureReading;
        in item temperature : TemperatureReading;
        out item command : MotorCommand;
    }
    action def GenerateTorque { in item command : MotorCommand; }
    action def PumpAir { in item inlet : Air; out item outlet : Air; }
    action def CoolAir { in item inlet : Air; out item outlet : Air; }
    action def StoreAir { in item inlet : Air; out item outlet : Air; }
    action def DeliverAir { in item inlet : Air; }
    action def CompressAir {
        doc /* Normal supply scenario. Successions state order; item flows state
               transfers. Allocations are declared responsibilities, not execution. */
        ref part controller : Controller;
        ref part motor : Motor;
        ref part pumpUnit : Pump;
        ref part cooler : CoolingAssembly;
        ref part tank : Tank;
        ref part regulator : CheckValve;
        action sense : SensePressure;
        action temperature : SenseTemperature;
        action control : ControlMotor;
        action torque : GenerateTorque;
        action pump : PumpAir;
        action cool : CoolAir;
        action store : StoreAir;
        action deliver : DeliverAir;
        allocation sensing allocate sense to controller;
        allocation thermalSensing allocate temperature to controller;
        allocation regulation allocate control to controller;
        allocation turning allocate torque to motor;
        allocation compression allocate pump to pumpUnit;
        allocation cooling allocate cool to cooler;
        allocation storage allocate store to tank;
        allocation delivery allocate deliver to regulator;
        first start then sense;
        first sense then temperature;
        first temperature then control;
        first control then torque;
        first torque then pump;
        first pump then cool;
        first cool then store;
        first store then deliver;
        first deliver then done;
        flow from sense.reading to control.reading;
        flow from temperature.reading to control.temperature;
        flow from control.command to torque.command;
        flow from pump.outlet to cool.inlet;
        flow from cool.outlet to store.inlet;
        flow from store.outlet to deliver.inlet;
    }
    action def IsolatePower;
    action def ReleasePressure;
    action def InspectEquipment;
    action def ReplaceFilter;
    action def RestoreService;
    action def ServiceCompressor {
        doc /* Maintenance follows isolation and depressurization. No completion
               or safety verification result is claimed by this activity. */
        ref part technician : Technician;
        ref part controller : Controller;
        ref part relief : ReliefValve;
        action isolate : IsolatePower;
        action depressurize : ReleasePressure;
        action inspect : InspectEquipment;
        action replaceFilter : ReplaceFilter;
        action restore : RestoreService;
        allocation isolation allocate isolate to controller;
        allocation venting allocate depressurize to relief;
        allocation inspection allocate inspect to technician;
        allocation replacement allocate replaceFilter to technician;
        allocation restoration allocate restore to controller;
        first start then isolate;
        first isolate then depressurize;
        first depressurize then inspect;
        first inspect then replaceFilter;
        first replaceFilter then restore;
        first restore then done;
    }
    item def StartRequest;
    item def StartupChecked;
    item def TankCharged;
    item def ToolDemand;
    item def PressureLow;
    item def TemperatureHigh;
    item def TemperatureNormal;
    item def FaultDetected;
    item def ResetRequested;
    item def StopRequest;
    item def ServiceRequested;
    item def ServiceComplete;
    state def OperatingMode {
        entry; then stopped;
        state stopped;
        state starting;
        state charging;
        state ready;
        state supplying;
        state cooling;
        state fault;
        state maintenance;
        transition startCharging first stopped accept StartRequest then starting;
        transition startupComplete first starting accept StartupChecked then charging;
        transition chargingComplete first charging accept TankCharged then ready;
        transition supply first ready accept ToolDemand then supplying;
        transition recharge first supplying accept PressureLow then charging;
        transition coolDown first charging accept TemperatureHigh then cooling;
        transition cooled first cooling accept TemperatureNormal then ready;
        transition detectFault first charging accept FaultDetected then fault;
        transition coolingFault first cooling accept FaultDetected then fault;
        transition reset first fault accept ResetRequested then stopped;
        transition stop first ready accept StopRequest then stopped;
        transition stopSupply first supplying accept StopRequest then stopped;
        transition beginService first stopped accept ServiceRequested then maintenance;
        transition endService first maintenance accept ServiceComplete then stopped;
    }
}

package CompressorComponents {
    private import ScalarValues::*;
    private import CompressorTypes::*;
    part def PowerSupply {
        attribute ratedPower : Real default = 2200.0;
        out port supply : PowerOutlet;
    }
    part def Controller {
        attribute shutdownDuration : Real default = 0.25;
        in port pressure : ~PressureOutlet;
        in port temperature : ~TemperatureOutlet;
        in port service : ~CommandOutlet;
        out port command : CommandOutlet;
        out port fanCommand : CommandOutlet;
        out port alarm : AlarmOutlet;
    }
    part def Motor {
        attribute ratedPower : Real default = 1500.0;
        in port power : ~PowerOutlet;
        in port command : ~CommandOutlet;
    }
    part def Pump {
        in port inlet : ~AirOutlet;
        out port outlet : AirOutlet;
        out port temperature : TemperatureOutlet;
    }
    part def Tank {
        attribute volume : Real default = 0.05;
        attribute pressure : Real default = 0.0;
        in port inlet : ~AirOutlet;
        out port delivery : AirOutlet;
        out port relief : AirOutlet;
        out port pressureReading : PressureOutlet;
    }
    part def Sensor {
        attribute accuracy : Real default = 0.01;
    }
    part def PressureSensor :> Sensor {
        in port sample : ~PressureOutlet;
        out port reading : PressureOutlet;
    }
    part def TemperatureSensor :> Sensor {
        attribute temperature : Real default = 293.15;
        in port sample : ~TemperatureOutlet;
        out port reading : TemperatureOutlet;
    }
    part def Valve {
        in port inlet : ~AirOutlet;
        out port outlet : AirOutlet;
    }
    part def CheckValve :> Valve {
        attribute deliveryPressure : Real default = 600000.0;
    }
    part def ReliefValve :> Valve {
        attribute openingPressure : Real default = 800000.0;
    }
    part def CoolingFan {
        attribute ratedPower : Real default = 120.0;
        in port command : ~CommandOutlet;
    }
    part def CoolingAssembly {
        part fan : CoolingFan;
        part temperature : TemperatureSensor;
    }
    part def ServiceConsole {
        out port request : CommandOutlet;
        in port alarm : ~AlarmOutlet;
    }
    part def CompressorInterface {
        doc /* Black-box interface used in the workshop context.
               Compressor specializes this definition with internal assemblies. */
        in port power : ~PowerOutlet;
        out port air : AirOutlet;
    }
    part def Operator;
    part def Technician;
    part def AirTool { in port inlet : ~AirOutlet; }
}

package CompressorGeometry {
    doc /* Envelope dimensions and placement. The preview centers the Box on its coordinate-frame origin. */
    attribute workshopDatum : ISQ::CartesianSpatial3dCoordinateFrame {
        :>> mRefs = (SI::m, SI::m, SI::m);
    }
    item enclosure : ShapeItems::Box {
        :>> length = 120 [SI::cm];
        :>> width = 80 [SI::cm];
        :>> height = 90 [SI::cm];
        attribute coordinateFrame : ISQ::CartesianSpatial3dCoordinateFrame {
            :>> mRefs = (SI::m, SI::m, SI::m);
            :>> transformation : MeasurementReferences::CoordinateFramePlacement {
                :>> source = workshopDatum;
                :>> origin = (1.5, 0.0, 0.45) [workshopDatum];
                :>> basisDirections = ((0.0, 1.0, 0.0) [workshopDatum],
                                      (-1.0, 0.0, 0.0) [workshopDatum],
                                      (0.0, 0.0, 1.0) [workshopDatum]);
            }
        }
    }
}

package CompressorRequirements {
    private import ScalarValues::*;
    private import CompressorComponents::*;
    private import CompressorSystem::*;
    requirement def <'COMP-001'> SafePressure {
        doc /* Tank pressure shall not exceed 800000 Pa. */
        subject tank : Tank;
        attribute maximum : Real default = 800000.0;
        require constraint pressureBound { tank.pressure <= maximum }
    }
    requirement def <'COMP-002'> StorageCapacity {
        doc /* The tank shall provide at least 0.05 cubic metres of storage. */
        subject tank : Tank;
        attribute minimum : Real default = 0.05;
        require constraint capacityBound { tank.volume >= minimum }
    }
    requirement def <'COMP-003'> ThermalLimit {
        doc /* Normal operation shall remain below 353.15 K (80 degrees Celsius). */
        subject sensor : TemperatureSensor;
        attribute maximum : Real default = 353.15;
        require constraint thermalBound { sensor.temperature <= maximum }
    }
    requirement def <'COMP-004'> SafeShutdown {
        doc /* The controller shall stop the motor within 1 s of detecting a fault. */
        subject controller : Controller;
        attribute maximum : Real default = 1.0;
        require constraint shutdownBound { controller.shutdownDuration <= maximum }
    }
    requirement def <'COMP-005'> DeliveryPressure {
        doc /* The regulated delivery setting shall be at least 600000 Pa. */
        subject regulator : CheckValve;
        attribute minimum : Real default = 600000.0;
        require constraint deliveryBound { regulator.deliveryPressure >= minimum }
    }
    requirement def <'COMP-006'> PressureProtection {
        doc /* The mechanical relief valve shall open at or below 800000 Pa. */
        subject valve : ReliefValve;
        attribute maximum : Real default = 800000.0;
        require constraint reliefBound { valve.openingPressure <= maximum }
    }
    requirement workshopSpecification {
        doc /* Bounds and declared trace links. Satisfaction assertions and
               verification cases are model declarations, not test evidence. */
        subject compressor : Compressor;
        requirement pressure : SafePressure { subject tank = compressor.pneumatic.tank; }
        requirement capacity : StorageCapacity { subject tank = compressor.pneumatic.tank; }
        requirement temperature : ThermalLimit { subject sensor = compressor.cooling.temperature; }
        requirement shutdown : SafeShutdown { subject controller = compressor.electrical.controller; }
        requirement delivery : DeliveryPressure { subject regulator = compressor.pneumatic.regulator; }
        requirement relief : PressureProtection { subject valve = compressor.pneumatic.relief; }
    }
    assert satisfy workshopSpecification.pressure by CompressorSystem::workshop.compressor.pneumatic.tank;
    assert satisfy workshopSpecification.capacity by CompressorSystem::workshop.compressor.pneumatic.tank;
    assert satisfy workshopSpecification.temperature by CompressorSystem::workshop.compressor.cooling.temperature;
    assert satisfy workshopSpecification.shutdown by CompressorSystem::workshop.compressor.electrical.controller;
    assert satisfy workshopSpecification.delivery by CompressorSystem::workshop.compressor.pneumatic.regulator;
    assert satisfy workshopSpecification.relief by CompressorSystem::workshop.compressor.pneumatic.relief;
    verification def CheckPressure {
        subject compressor : Compressor;
        objective pressureCheck { verify workshopSpecification.pressure; }
    }
    verification def CheckShutdown {
        subject compressor : Compressor;
        objective shutdownCheck { verify workshopSpecification.shutdown; }
    }
    verification pressureTest : CheckPressure { subject compressor = CompressorSystem::workshop.compressor; }
    verification shutdownTest : CheckShutdown { subject compressor = CompressorSystem::workshop.compressor; }
}

package CompressorSequence {
    item def AirDelivery;
    item def AirDemand;
    item def FaultNotice;
    item def PowerCommand;
    item def PressureReading;
    item def ReadyNotice;
    item def ResetCommand;
    item def SensorQuery;
    item def StartCommand;
    item def StopCommand;
    item def TemperatureReading;

    occurrence def Startup {
        part operator {
            event occurrence startSent;
            then event occurrence readyReceived;
        }
        part controller {
            event occurrence startReceived;
            then event occurrence checkSent;
            then event occurrence temperatureReceived;
            then event occurrence energizeSent;
            then event occurrence feedbackReceived;
            then event occurrence readySent;
        }
        part sensor {
            event occurrence checkReceived;
            then event occurrence temperatureSent;
        }
        part motor {
            event occurrence energizeReceived;
            then event occurrence driveSent;
        }
        part pump {
            event occurrence driveReceived;
            then event occurrence feedbackSent;
        }
        message start of StartCommand from operator.startSent to controller.startReceived;
        message check of SensorQuery from controller.checkSent to sensor.checkReceived;
        message temperature of TemperatureReading from sensor.temperatureSent to controller.temperatureReceived;
        message energize of PowerCommand from controller.energizeSent to motor.energizeReceived;
        message drive of PowerCommand from motor.driveSent to pump.driveReceived;
        message feedback of PressureReading from pump.feedbackSent to controller.feedbackReceived;
        message ready of ReadyNotice from controller.readySent to operator.readyReceived;
    }

    occurrence def ToolDemand {
        part tool {
            event occurrence requestSent;
            then event occurrence deliverReceived;
        }
        part tank {
            event occurrence requestReceived;
            then event occurrence deliverSent;
            then event occurrence pressureSent;
            then event occurrence refillReceived;
        }
        part controller {
            event occurrence pressureReceived;
            then event occurrence rechargeSent;
        }
        part motor {
            event occurrence rechargeReceived;
            then event occurrence driveSent;
        }
        part pump {
            event occurrence driveReceived;
            then event occurrence refillSent;
        }
        message request of AirDemand from tool.requestSent to tank.requestReceived;
        message deliver of AirDelivery from tank.deliverSent to tool.deliverReceived;
        message pressure of PressureReading from tank.pressureSent to controller.pressureReceived;
        message recharge of PowerCommand from controller.rechargeSent to motor.rechargeReceived;
        message drive of PowerCommand from motor.driveSent to pump.driveReceived;
        message refill of AirDelivery from pump.refillSent to tank.refillReceived;
    }

    occurrence def OverheatShutdown {
        part sensor {
            event occurrence overheatSent;
        }
        part controller {
            event occurrence overheatReceived;
            then event occurrence stopMotorSent;
            then event occurrence coolSent;
            then event occurrence alarmSent;
            then event occurrence acknowledgeReceived;
            then event occurrence resetSent;
        }
        part motor {
            event occurrence stopMotorReceived;
            then event occurrence resetReceived;
        }
        part fan {
            event occurrence coolReceived;
        }
        part operator {
            event occurrence alarmReceived;
            then event occurrence acknowledgeSent;
        }
        message overheat of TemperatureReading from sensor.overheatSent to controller.overheatReceived;
        message stopMotor of StopCommand from controller.stopMotorSent to motor.stopMotorReceived;
        message cool of PowerCommand from controller.coolSent to fan.coolReceived;
        message alarm of FaultNotice from controller.alarmSent to operator.alarmReceived;
        message acknowledge of ResetCommand from operator.acknowledgeSent to controller.acknowledgeReceived;
        message reset of StopCommand from controller.resetSent to motor.resetReceived;
    }
}

package CompressorSystem {
    private import ScalarValues::*;
    private import CompressorTypes::*;
    private import CompressorComponents::*;
    private import CompressorBehavior::*;
    part def Compressor :> CompressorInterface {
        doc /* Smart compressor: electrical control, air storage and cooling.
               These are authored connections and constraints, not a simulation. */
        part electrical : ElectricalAssembly;
        part pneumatic : PneumaticAssembly;
        part cooling : CoolingAssembly;
        part serviceConsole : ServiceConsole;
        connection pressureFeedback connect pneumatic.pressureSensor.reading
            to electrical.controller.pressure;
        connection temperatureSample connect pneumatic.pump.temperature
            to cooling.temperature.sample;
        connection temperatureFeedback connect cooling.temperature.reading
            to electrical.controller.temperature;
        connection fanControl connect electrical.controller.fanCommand to cooling.fan.command;
        connection maintenanceRequest connect serviceConsole.request to electrical.controller.service;
        connection faultAlarm connect electrical.controller.alarm to serviceConsole.alarm;
        constraint powerBudget {
            electrical.motor.ratedPower + cooling.fan.ratedPower <= electrical.supply.ratedPower
        }
        action startup : CompressAir;
        action service : ServiceCompressor;
        state operatingMode : OperatingMode;
    }
    part def ElectricalAssembly {
        part supply : PowerSupply;
        part controller : Controller;
        part motor : Motor;
        connection motorPower connect supply.supply to motor.power;
        connection motorControl connect controller.command to motor.command;
    }
    part def PneumaticAssembly {
        part pump : Pump;
        part tank : Tank;
        part regulator : CheckValve;
        part relief : ReliefValve;
        part pressureSensor : PressureSensor;
        connection chargingLine connect pump.outlet to tank.inlet;
        connection regulatedDelivery connect tank.delivery to regulator.inlet;
        connection pressureProtection connect tank.relief to relief.inlet;
        connection pressureSample connect tank.pressureReading to pressureSensor.sample;
    }
    part def Workshop {
        part compressor : Compressor;
        part spareCompressor : Compressor;
        part tool : AirTool;
        part blowGun : AirTool;
        part operator : Operator;
        part technician : Technician;
        connection deliveryLine connect compressor.pneumatic.regulator.outlet to tool.inlet;
        connection spareDelivery connect spareCompressor.pneumatic.regulator.outlet to blowGun.inlet;
    }
    part def WorkshopContext {
        doc /* A black-box system context. The two compressor roles share the
               interface specialized by the detailed Compressor definition. */
        part mains : PowerSupply;
        part compressor : CompressorInterface;
        part tool : AirTool;
        part serviceConsole : ServiceConsole;
        connection electricalSupply connect mains.supply to compressor.power;
        connection usableAir connect compressor.air to tool.inlet;
    }
    part workshop : Workshop;
}

package CompressorTypes {
    doc /* Showcase quantities use documented SI units: pressure in Pa,
           volume in cubic metres, power in W, time in seconds, and temperature in kelvin. */
    item def Air;
    item def ElectricalPower;
    item def PressureReading;
    item def MotorCommand;
    item def TemperatureReading;
    item def Alarm;
    port def AirOutlet { out item air : Air; }
    port def PowerOutlet { out item electricity : ElectricalPower; }
    port def PressureOutlet { out item reading : PressureReading; }
    port def TemperatureOutlet { out item reading : TemperatureReading; }
    port def AlarmOutlet { out item alarm : Alarm; }
    port def CommandOutlet { out item command : MotorCommand; }
}

package CompressorUseCases {
    private import CompressorComponents::*;
    private import CompressorSystem::*;
    use case def ChargeTank {
        subject compressor : Compressor;
        actor operator : Operator;
        objective { doc /* Build a usable supply of compressed air. */ }
    }
    use case def SupplyAir {
        subject compressor : Compressor;
        actor operator : Operator;
        objective { doc /* Supply regulated compressed air to workshop tools. */ }
    }
    use case def ProtectEquipment {
        subject compressor : Compressor;
        actor operator : Operator;
        objective { doc /* Stop the motor, cool the equipment and notify the operator on overheating. */ }
    }
    use case def RecoverFromFault {
        subject compressor : Compressor;
        actor operator : Operator;
        objective { doc /* Acknowledge the fault and return to a stopped state before restarting. */ }
    }
    use case def MaintainEquipment {
        subject compressor : Compressor;
        actor technician : Technician;
        objective { doc /* Isolate, depressurize, inspect and service the compressor. */ }
    }
    use case operateWorkshop {
        subject compressor : Compressor;
        actor operator : Operator;
        actor technician : Technician;
        objective { doc /* Keep workshop tools supplied with air while protecting equipment and enabling maintenance. */ }
        include use case charge : ChargeTank {
            subject compressor;
            actor operator = operateWorkshop::operator;
        }
        include use case supply : SupplyAir {
            subject compressor;
            actor operator = operateWorkshop::operator;
        }
        include use case protect : ProtectEquipment {
            subject compressor;
            actor operator = operateWorkshop::operator;
        }
        include use case recover : RecoverFromFault {
            subject compressor;
            actor operator = operateWorkshop::operator;
        }
        include use case service : MaintainEquipment {
            subject compressor;
            actor technician = operateWorkshop::technician;
        }
    }
}

